/**
 * Physics XI Academic Companion — typed registry.
 *
 * The canonical dataset lives at `public/data/physics-xi-academic/units.json`
 * and is the single source of truth for:
 *   • the published companion documents (HTML + Word-compatible .doc pairs)
 *     generated by `scripts/generate-physics-academic-docs.mjs`, and
 *   • the reading surface at `/resources/physics-xi`.
 *
 * Every unit brief answers four questions: what the model asserts, the
 * conditions under which it holds, the questions that are still open, and
 * where to read further.
 */
import dataset from "@/public/data/physics-xi-academic/units.json";

export interface PhysicsXiMystery {
  question: string;
  status: string;
  note: string;
}

export interface PhysicsXiKeyNumber {
  label: string;
  value: string;
}

export interface PhysicsXiSource {
  label: string;
  url: string;
}

export interface PhysicsXiUnit {
  unitNo: number;
  unitId: string;
  unitName: string;
  contentArea: string;
  slug: string;
  summary: string;
  facts: string[];
  conditions: string[];
  mysteries: PhysicsXiMystery[];
  prompts: string[];
  keyNumbers: PhysicsXiKeyNumber[];
  sources: PhysicsXiSource[];
}

export interface PhysicsXiAcademicDataset {
  title: string;
  subtitle: string;
  course: string;
  units: PhysicsXiUnit[];
}

export const PHYSICS_XI_ACADEMIC: PhysicsXiAcademicDataset = dataset;

export const PHYSICS_XI_ACADEMIC_UNITS: PhysicsXiUnit[] = PHYSICS_XI_ACADEMIC.units;

/** Content areas in curriculum order — the filter axis of the reading surface. */
export const PHYSICS_XI_CONTENT_AREAS: string[] = Array.from(
  new Set(PHYSICS_XI_ACADEMIC_UNITS.map((unit) => unit.contentArea)),
);

/** Where the published documents are served from (static files under /public). */
export const PHYSICS_XI_ACADEMIC_DOC_BASE = "/resources/physics-xi";

export type PhysicsXiDocExtension = "html" | "doc";

export function physicsXiDocFileName(
  unit: Pick<PhysicsXiUnit, "slug">,
  extension: PhysicsXiDocExtension,
): string {
  return `${unit.slug}.${extension}`;
}

export function physicsXiDocUrl(
  unit: Pick<PhysicsXiUnit, "slug">,
  extension: PhysicsXiDocExtension,
): string {
  return `${PHYSICS_XI_ACADEMIC_DOC_BASE}/${physicsXiDocFileName(unit, extension)}`;
}

/** Where a unit brief lives on the platform (its own deep-linkable page). */
export function physicsXiUnitHref(unit: Pick<PhysicsXiUnit, "unitId">): string {
  return `/resources/physics-xi/${unit.unitId}`;
}

export function getPhysicsXiUnitById(unitId: string): PhysicsXiUnit | undefined {
  return PHYSICS_XI_ACADEMIC_UNITS.find((unit) => unit.unitId === unitId);
}

export function getPhysicsXiUnitByNumber(unitNo: number): PhysicsXiUnit | undefined {
  return PHYSICS_XI_ACADEMIC_UNITS.find((unit) => unit.unitNo === unitNo);
}

/** True when a unit brief carries every section the published document needs. */
export function isCompletePhysicsXiUnit(unit: PhysicsXiUnit): boolean {
  return (
    unit.facts.length > 0 &&
    unit.conditions.length > 0 &&
    unit.mysteries.length > 0 &&
    unit.prompts.length > 0 &&
    unit.keyNumbers.length > 0 &&
    unit.sources.length > 0
  );
}
